-- Datos sinteticos para proyecciones: jueves 24/09/2026 00:00 Lima -> 2026-09-26 12:30:00 Lima.
-- Fechas en UTC (igual que el backend). Cultivo 2 'Lechugas Colegio', usuario 2, modelo 2 'Random Forest Lechugas'.
-- Asignaciones: 12 hum. suelo, 13 temp. ambiente, 14 hum. ambiente, 15 temp. suelo, 9 bomba/flujometro.
-- Logica igual al scheduler ML: tras cada riego hay cooldown de 120 min sin evaluar; cumplido el
-- cooldown el modelo evalua cada lectura (5 min) y guarda la prediccion; si predice 'regar' el riego
-- arranca en ese instante (riego.id_prediccion enlazado) y dura 5 min.
-- Idempotente: primero borra lo sintetico de corridas anteriores (sin microsegundos); lo real se conserva.
BEGIN;

DELETE FROM riego WHERE id_asignacion = 9 AND fecha_inicio >= '2026-09-24 05:00:00' AND fecha_inicio = date_trunc('second', fecha_inicio);
DELETE FROM predicciones_ml WHERE id_cultivo = 2 AND fecha >= '2026-09-24 05:00:00' AND fecha = date_trunc('second', fecha)
  AND id NOT IN (SELECT id_prediccion FROM riego WHERE id_prediccion IS NOT NULL);
DELETE FROM humedad_suelo WHERE id_asignacion = 12 AND fecha >= '2026-09-24 05:00:00' AND fecha = date_trunc('second', fecha);
DELETE FROM temperatura_ambiente WHERE id_asignacion = 13 AND fecha >= '2026-09-24 05:00:00' AND fecha = date_trunc('second', fecha);
DELETE FROM humedad_ambiente WHERE id_asignacion = 14 AND fecha >= '2026-09-24 05:00:00' AND fecha = date_trunc('second', fecha);
DELETE FROM temperatura_suelo WHERE id_asignacion = 15 AND fecha >= '2026-09-24 05:00:00' AND fecha = date_trunc('second', fecha);

-- humedad_suelo (714 filas)

-- temperatura_ambiente (714 filas)

-- humedad_ambiente (714 filas)

-- temperatura_suelo (714 filas)

-- predicciones_ml sin riego (584 evaluaciones 'no_regar' despues del cooldown)

-- 4 riegos automaticos disparados por una prediccion 'regar'
WITH p AS (
  VALUES (2, 2, 2, '{"humedad_suelo": 56.2, "humedad_ambiente": 95.78, "temperatura_suelo": 19.39, "temperatura_ambiente": 17.33}'::jsonb, 'regar', 0.54, TRUE, 'sistema_ml', '2026-09-24 06:50:00')
  RETURNING id),
r AS (
                     cantidad_agua_litros, motivo_cierre, estado, fecha_inicio, fecha_fin, fecha)
  SELECT 9, 2, 2, p.id, 'automatico_ml', 306, 306, 4.21, 'cronometro_completado', TRUE, '2026-09-24 06:50:01', '2026-09-24 06:55:07', '2026-09-24 06:55:07' FROM p
  RETURNING id)
SELECT id, 'flujometro', '2026-09-24 06:50:01', '2026-09-24 06:55:07', 306, 4.21, 'cronometro_completado' FROM r;

WITH p AS (
  VALUES (2, 2, 2, '{"humedad_suelo": 59.06, "humedad_ambiente": 70.66, "temperatura_suelo": 22.49, "temperatura_ambiente": 24.92}'::jsonb, 'regar', 0.54, TRUE, 'sistema_ml', '2026-09-24 21:50:00')
  RETURNING id),
r AS (
                     cantidad_agua_litros, motivo_cierre, estado, fecha_inicio, fecha_fin, fecha)
  SELECT 9, 2, 2, p.id, 'automatico_ml', 303, 303, 4.10, 'cronometro_completado', TRUE, '2026-09-24 21:50:01', '2026-09-24 21:55:04', '2026-09-24 21:55:04' FROM p
  RETURNING id)
SELECT id, 'flujometro', '2026-09-24 21:50:01', '2026-09-24 21:55:04', 303, 4.10, 'cronometro_completado' FROM r;

WITH p AS (
  VALUES (2, 2, 2, '{"humedad_suelo": 59.67, "humedad_ambiente": 62.63, "temperatura_suelo": 22.61, "temperatura_ambiente": 27.24}'::jsonb, 'regar', 0.58, TRUE, 'sistema_ml', '2026-09-25 18:55:00')
  RETURNING id),
r AS (
                     cantidad_agua_litros, motivo_cierre, estado, fecha_inicio, fecha_fin, fecha)
  SELECT 9, 2, 2, p.id, 'automatico_ml', 304, 304, 3.92, 'cronometro_completado', TRUE, '2026-09-25 18:55:01', '2026-09-25 19:00:05', '2026-09-25 19:00:05' FROM p
  RETURNING id)
SELECT id, 'flujometro', '2026-09-25 18:55:01', '2026-09-25 19:00:05', 304, 3.92, 'cronometro_completado' FROM r;

WITH p AS (
  VALUES (2, 2, 2, '{"humedad_suelo": 58.16, "humedad_ambiente": 77.94, "temperatura_suelo": 20.19, "temperatura_ambiente": 22.37}'::jsonb, 'regar', 0.56, TRUE, 'sistema_ml', '2026-09-26 12:30:00')
  RETURNING id),
r AS (
                     cantidad_agua_litros, motivo_cierre, estado, fecha_inicio, fecha_fin, fecha)
  SELECT 9, 2, 2, p.id, 'automatico_ml', 307, 307, 4.02, 'cronometro_completado', TRUE, '2026-09-26 12:30:01', '2026-09-26 12:35:08', '2026-09-26 12:35:08' FROM p
  RETURNING id)
SELECT id, 'flujometro', '2026-09-26 12:30:01', '2026-09-26 12:35:08', 307, 4.02, 'cronometro_completado' FROM r;

COMMIT;

-- =====================================================================
-- DATASET PARA PROYECCIONES (solo lectura, ejecutar despues del COMMIT)
-- Una fila por lectura con las 4 variables, el tiempo desde el ultimo
-- riego terminado (riego.fecha_fin, mismo criterio que controlServ para
-- "tiempoDesdeUltimoRiegoSeg") y la prediccion ML de ese instante.
-- prediccion NULL = el scheduler no evaluo (cooldown de 120 min o riego en curso).
-- fecha_lima = hora local (UTC-5); fecha se guarda en UTC.
-- =====================================================================
SELECT
    hs.fecha - INTERVAL '5 hours'                          AS fecha_lima,
    hs.valor                                               AS humedad_suelo,
    ha.valor                                               AS humedad_ambiente,
    ta.temperatura                                         AS temperatura_ambiente,
    ts.temperatura                                         AS temperatura_suelo,
    ur.fecha_fin - INTERVAL '5 hours'                      AS ultimo_riego_lima,
    ur.cantidad_agua_litros                                AS litros_ultimo_riego,
    ROUND(EXTRACT(EPOCH FROM hs.fecha - ur.fecha_fin) / 60)::INT  AS minutos_desde_ultimo_riego,
    ROUND((EXTRACT(EPOCH FROM hs.fecha - ur.fecha_fin) / 3600)::NUMERIC, 2) AS horas_desde_ultimo_riego,
    p.recomendacion                                        AS prediccion_ml,
    p.probabilidad                                         AS probabilidad_regar,
    (r.id IS NOT NULL)                                     AS riego_disparado
FROM humedad_suelo hs
JOIN humedad_ambiente     ha ON ha.id_asignacion = 14 AND ha.fecha = hs.fecha
JOIN temperatura_ambiente ta ON ta.id_asignacion = 13 AND ta.fecha = hs.fecha
JOIN temperatura_suelo    ts ON ts.id_asignacion = 15 AND ts.fecha = hs.fecha
LEFT JOIN predicciones_ml p  ON p.id_cultivo = 2 AND p.fecha = hs.fecha
LEFT JOIN riego r            ON r.id_prediccion = p.id
LEFT JOIN LATERAL (
    SELECT COALESCE(x.fecha_fin, x.fecha) AS fecha_fin, x.cantidad_agua_litros
    FROM riego x
    WHERE x.id_asignacion = 9
      AND COALESCE(x.fecha_fin, x.fecha) <= hs.fecha
    ORDER BY COALESCE(x.fecha_fin, x.fecha) DESC
    LIMIT 1
) ur ON TRUE
WHERE hs.id_asignacion = 12
  AND hs.valido
  AND hs.valor IS NOT NULL
  AND hs.fecha >= '2026-09-24 05:00:00'   -- jueves 00:00 Lima
ORDER BY hs.fecha;

